const input = $input.first().json.message.text.trim().toUpperCase();

// Crypto → Yahoo format: BTC-USD
const cryptoMap = {
  'BTC': 'BTC-USD', 'BITCOIN': 'BTC-USD',
  'ETH': 'ETH-USD', 'ETHEREUM': 'ETH-USD',
  'SOL': 'SOL-USD', 'SOLANA': 'SOL-USD',
  'XRP': 'XRP-USD', 'ADA': 'ADA-USD',
  'DOGE': 'DOGE-USD', 'DOGECOIN': 'DOGE-USD',
  'DOT': 'DOT-USD', 'POLKADOT': 'DOT-USD',
  'AVAX': 'AVAX-USD', 'AVALANCHE': 'AVAX-USD',
  'MATIC': 'MATIC-USD', 'POLYGON': 'MATIC-USD',
  'LINK': 'LINK-USD', 'CHAINLINK': 'LINK-USD',
  'BNB': 'BNB-USD', 'UNI': 'UNI-USD',
  'ATOM': 'ATOM-USD', 'NEAR': 'NEAR-USD',
  'APT': 'APT-USD', 'ARB': 'ARB-USD',
  'OP': 'OP-USD', 'SUI': 'SUI-USD',
};

// Index → Yahoo format: ^SYMBOL
const indexMap = {
  'SPX': '^GSPC', 'S&P': '^GSPC', 'S&P500': '^GSPC', 'SP500': '^GSPC',
  'NASDAQ': '^IXIC', 'QQQ': 'QQQ',
  'DOW': '^DJI', 'DJIA': '^DJI',
  'IBEX': '^IBEX', 'IBEX35': '^IBEX',
  'FTSE': '^FTSE', 'DAX': '^GDAXI',
  'NIKKEI': '^N225', 'N225': '^N225',
  'CAC40': '^FCHI', 'HANGSENG': '^HSI',
  'EUROSTOXX': '^STOXX50E',
};

// Commodity → Yahoo format: SYMBOL=F
const commodityMap = {
  'GOLD': 'GC=F', 'SILVER': 'SI=F',
  'OIL': 'CL=F', 'CRUDE': 'CL=F', 'WTI': 'CL=F',
  'BRENT': 'BZ=F', 'GAS': 'NG=F', 'NATGAS': 'NG=F',
  'COPPER': 'HG=F', 'PLATINUM': 'PL=F',
  'CORN': 'ZC=F', 'WHEAT': 'ZW=F', 'COCOA': 'CC=F',
  'SUGAR': 'SB=F', 'COFFEE': 'KC=F', 'COTTON': 'CT=F',
};

let assetType = 'stock';
let ticker = input;
let displayName = input;

if (cryptoMap[input]) {
  assetType = 'crypto';
  ticker = cryptoMap[input];
  displayName = input;
} else if (indexMap[input]) {
  assetType = 'index';
  ticker = indexMap[input];
  displayName = input;
} else if (commodityMap[input]) {
  assetType = 'commodity';
  ticker = commodityMap[input];
  displayName = input;
}

const chatId = $input.first().json.message.chat.id;

return [{
  json: {
    ticker,
    assetType,
    displayName,
    originalInput: input,
    chatId
  }
}];

const chartData = $input.first().json.chart.result[0];
const meta = chartData.meta;
const timestamps = chartData.timestamp;
const closes = chartData.indicators.adjclose[0].adjclose;

// ---- Dynamic company name & currency ----
const companyName = meta.longName || meta.shortName || meta.symbol || 'Unknown';
const currency = meta.currency || 'USD';

// Currency symbol mapping
const currencySymbols = {
  'USD': '$', 'EUR': '€', 'GBP': '£', 'JPY': '¥',
  'CHF': 'CHF ', 'CAD': 'C$', 'AUD': 'A$', 'HKD': 'HK$',
  'CNY': '¥', 'KRW': '₩', 'INR': '₹', 'BRL': 'R$',
  'SEK': 'kr', 'NOK': 'kr', 'DKK': 'kr', 'SGD': 'S$',
  'MXN': 'MX$', 'ZAR': 'R', 'TRY': '₺', 'PLN': 'zł',
  'ILS': '₪', 'TWD': 'NT$', 'THB': '฿', 'MYR': 'RM',
};
const currencySymbol = currencySymbols[currency] || currency + ' ';

// ---- Price calculations ----
const currentPrice = closes[closes.length - 1];
const prevClose = closes[closes.length - 2];

// YTD start
const currentYear = new Date().getFullYear();
let ytdStartPrice = null;
for (let i = 0; i < timestamps.length; i++) {
  const date = new Date(timestamps[i] * 1000);
  if (date.getFullYear() === currentYear) {
    ytdStartPrice = closes[i];
    break;
  }
}

// YoY = first data point (~1 year ago)
const yoyStartPrice = closes[0];

// Growth percentages
const ytdGrowth = ytdStartPrice
  ? ((currentPrice - ytdStartPrice) / ytdStartPrice * 100).toFixed(2)
  : 'N/A';
const yoyGrowth = ((currentPrice - yoyStartPrice) / yoyStartPrice * 100).toFixed(2);
const dailyChange = ((currentPrice - prevClose) / prevClose * 100).toFixed(2);

// Get ticker info from parser node
const prevData = $('Code in JavaScript').first().json;

return [{
  json: {
    ticker: prevData.ticker,
    assetType: prevData.assetType,
    displayName: companyName,
    chatId: prevData.chatId,
    currency,
    currencySymbol,
    currentPrice: currentPrice.toFixed(2),
    prevClose: prevClose.toFixed(2),
    dailyChange,
    ytdGrowth,
    yoyGrowth
  }
}];

const news = $input.first().json.news || [];
const metrics = $('Calculate Metrics').first().json;

// Format top 3 news articles
const newsFormatted = news.slice(0, 3).map((article, i) => {
  const title = article.title || 'No title';
  const publisher = article.publisher || 'Unknown';
  const link = article.link || '';
  return `${i + 1}. *${title}*\n   _${publisher}_\n   ${link}`;
}).join('\n\n');

return [{
  json: {
    ...metrics,
    newsFormatted,
    newsRaw: news.slice(0, 3)
  }
}];

const d = $input.first().json;

const prompt = `You are a senior equity/macro research analyst at a top-tier investment bank. Produce a concise but high-signal research flash note for the following asset.

ASSET PROFILE:
Name: ${d.displayName}
Ticker: ${d.ticker}
Asset Class: ${d.assetType}
Currency: ${d.currency}

MARKET DATA:
Current Price: ${d.currencySymbol}${d.currentPrice}
Previous Close: ${d.currencySymbol}${d.prevClose}
Daily Change: ${d.dailyChange}%
YTD Performance: ${d.ytdGrowth}%
YoY Performance: ${d.yoyGrowth}%

RECENT HEADLINES:
${d.newsRaw.map((a, i) => `${i+1}. ${a.title} (${a.publisher})`).join('\n')}

FORMAT YOUR RESPONSE EXACTLY AS FOLLOWS:

SECTOR: [Identify the sector and industry this asset belongs to, e.g. "Technology | Software & IT Services" or "Commodities | Precious Metals"]

MARKET SNAPSHOT
Analyze the price action: is the asset trending up, down, or consolidating? Put the daily move in context of the YTD and YoY trajectory. Mention key levels if obvious from the data. 2-3 sentences max.

NEWS IMPACT
For each headline, assess the likely market impact: bullish, bearish, or neutral catalyst. Connect headlines to the price action where possible. One sentence per headline. IMPORTANT: Only analyze news that is directly about ${d.displayName}. Ignore any headline that refers to a different company or asset.

RISK FACTORS
Identify 2-3 key risks or catalysts to watch based on the data and headlines. Be specific — name sectors, macro drivers, or corporate events.

OUTLOOK
Synthesize a 2-3 sentence forward-looking view. What is the most probable near-term direction? What would change the thesis?

RULES:
- Use plain text only, no markdown, no asterisks, no bullet points
- Reference actual numbers from the data
- Be direct and opinionated like a real analyst, not generic
- Keep total length under 1200 characters
- Only discuss ${d.displayName} — do not mention unrelated companies from the headlines
- End with: This is an automated summary, not financial advice.`;

return [{
  json: {
    ...d,
    requestBody: {
      model: "claude-sonnet-4-20250514",
      max_tokens: 1024,
      messages: [
        { role: "user", content: prompt }
      ]
    }
  }
}];

const d = $('Build LLM Prompt').first().json;
const aiText = $input.first().json.content[0].text;
const now = new Date().toLocaleDateString('en-GB', { 
  day: 'numeric', month: 'long', year: 'numeric' 
});

// Color logic
const dailyColor = parseFloat(d.dailyChange) >= 0 ? '#10b981' : '#ef4444';
const ytdColor = parseFloat(d.ytdGrowth) >= 0 ? '#10b981' : '#ef4444';
const yoyColor = parseFloat(d.yoyGrowth) >= 0 ? '#10b981' : '#ef4444';
const dailyArrow = parseFloat(d.dailyChange) >= 0 ? '▲' : '▼';
const ytdArrow = parseFloat(d.ytdGrowth) >= 0 ? '▲' : '▼';
const yoyArrow = parseFloat(d.yoyGrowth) >= 0 ? '▲' : '▼';

// Format AI text into paragraphs
const aiHtml = aiText.split('\n').filter(l => l.trim()).map(l => {
  if (l.match(/^(SECTOR:|MARKET SNAPSHOT|NEWS IMPACT|RISK FACTORS|OUTLOOK)/)) {
    return `<h3 style="color:#1e3a5f; margin:18px 0 6px 0; font-size:13px; text-transform:uppercase; letter-spacing:1px; border-bottom:1px solid #e2e8f0; padding-bottom:4px;">${l}</h3>`;
  }
  return `<p style="margin:4px 0; line-height:1.5;">${l}</p>`;
}).join('\n');

// News section
const newsHtml = d.newsRaw.slice(0, 3).map((a, i) => 
  `<div style="margin-bottom:10px;">
    <span style="color:#1e3a5f; font-weight:600;">${i+1}.</span> 
    <a href="${a.link}" style="color:#2563eb; text-decoration:none;">${a.title}</a>
    <br><span style="color:#94a3b8; font-size:11px;">${a.publisher || ''}</span>
  </div>`
).join('');

const html = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width:660px; margin:0 auto; padding:40px; color:#1e293b; font-size:13px;">

  <div style="border-bottom:3px solid #1e3a5f; padding-bottom:16px; margin-bottom:24px;">
    <h1 style="margin:0; color:#1e3a5f; font-size:22px;">${d.displayName}</h1>
    <p style="margin:4px 0 0 0; color:#64748b; font-size:13px;">
      Ticker: <strong>${d.ticker}</strong> | Currency: <strong>${d.currency}</strong> | Report Date: ${now}
    </p>
  </div>

  <table style="width:100%; border-collapse:collapse; margin-bottom:24px;">
    <tr style="background:#f8fafc;">
      <td style="padding:12px; border:1px solid #e2e8f0;"><strong>Current Price</strong></td>
      <td style="padding:12px; border:1px solid #e2e8f0; text-align:right; font-size:18px; font-weight:700;">
        ${d.currencySymbol}${d.currentPrice}
      </td>
    </tr>
    <tr>
      <td style="padding:10px 12px; border:1px solid #e2e8f0;">Previous Close</td>
      <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right;">${d.currencySymbol}${d.prevClose}</td>
    </tr>
    <tr style="background:#f8fafc;">
      <td style="padding:10px 12px; border:1px solid #e2e8f0;">Daily Change</td>
      <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:${dailyColor}; font-weight:600;">
        ${dailyArrow} ${d.dailyChange}%
      </td>
    </tr>
    <tr>
      <td style="padding:10px 12px; border:1px solid #e2e8f0;">YTD Growth</td>
      <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:${ytdColor}; font-weight:600;">
        ${ytdArrow} ${d.ytdGrowth}%
      </td>
    </tr>
    <tr style="background:#f8fafc;">
      <td style="padding:10px 12px; border:1px solid #e2e8f0;">YoY Growth</td>
      <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:${yoyColor}; font-weight:600;">
        ${yoyArrow} ${d.yoyGrowth}%
      </td>
    </tr>
  </table>

  <div style="margin-bottom:24px;">
    <h2 style="color:#1e3a5f; font-size:15px; border-bottom:2px solid #e2e8f0; padding-bottom:6px;">AI Research Analysis</h2>
    ${aiHtml}
  </div>

  <div style="margin-bottom:24px;">
    <h2 style="color:#1e3a5f; font-size:15px; border-bottom:2px solid #e2e8f0; padding-bottom:6px;">Latest News</h2>
    ${newsHtml}
  </div>

  <div style="margin-top:32px; padding-top:16px; border-top:1px solid #e2e8f0; color:#94a3b8; font-size:10px;">
    <p>This report was automatically generated. It is not financial advice. Data sourced from Yahoo Finance. AI analysis powered by Claude (Anthropic).</p>
  </div>
</body>
</html>`;

return [{
  json: {
    ...d,
    aiSummary: aiText,
    reportHtml: html,
    fileName: `${d.ticker.replace(/[^a-zA-Z0-9]/g, '_')}_Report_${new Date().toISOString().split('T')[0]}.pdf`
  }
}];

